package org.shield.browser;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import org.json.*;
import org.mozilla.geckoview.*;
import java.io.*;
import java.nio.channels.FileChannel;
import java.util.*;
import java.util.concurrent.*;

/** Visible-app transfers consume Gecko streams; leaving the browser pauses transfers. */
public final class DownloadService extends Service {
 static final Object LOCK=new Object();
 static final Map<String,Transfer> active=new ConcurrentHashMap<>(),queued=new ConcurrentHashMap<>();
 static final Set<GeckoSession> detached=Collections.newSetFromMap(new IdentityHashMap<>());
 final ExecutorService io=Executors.newFixedThreadPool(2);
 final Handler main=new Handler(Looper.getMainLooper());
 PowerManager.WakeLock wakeLock;
 static final String CHANNEL="browser_downloads";static volatile boolean visible; static DownloadService instance;
 static final class Transfer {
  final JSONObject item;WebResponse response;GeckoSession session;boolean ownSession;volatile boolean paused;volatile InputStream input;
  Transfer(JSONObject o,WebResponse r,GeckoSession s){item=o;response=r;session=s;}
 }
 static String header(WebResponse r,String key){for(Map.Entry<String,String> e:r.headers.entrySet())if(key.equalsIgnoreCase(e.getKey()))return e.getValue()==null?"":e.getValue();return "";}
 static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(Exception ignored){}}
 static JSONArray records(Context c){try{return new JSONArray(c.getSharedPreferences("browser",0).getString("downloads","[]"));}catch(Exception e){return new JSONArray();}}
 static void update(Context c,JSONObject item){synchronized(LOCK){JSONArray next=new JSONArray(),old=records(c);next.put(item);for(int i=0;i<old.length();i++){JSONObject o=old.optJSONObject(i);if(o!=null&&!o.optString("id").equals(item.optString("id")))next.put(o);}c.getSharedPreferences("browser",0).edit().putString("downloads",next.toString()).commit();}}
 static JSONObject find(Context c,String id){synchronized(LOCK){JSONArray list=records(c);for(int i=0;i<list.length();i++){JSONObject o=list.optJSONObject(i);if(o!=null&&id.equals(o.optString("id")))return o;}}return null;}
 static boolean isPinned(GeckoSession session){for(Transfer t:active.values())if(t.session==session)return true;for(Transfer t:queued.values())if(t.session==session)return true;return false;}
 static void detach(GeckoSession s){detached.add(s);s.setProgressDelegate(null);s.setContentDelegate(null);s.setNavigationDelegate(null);}
 static void enqueue(Context c,GeckoSession session,WebResponse r,String name,String mime,Uri destination){if(DownloadPolicy.blocked(name,mime,r.uri,header(r,"Content-Disposition"),header(r,"Content-Type"))){close(r.body);return;}JSONObject item=new JSONObject();String id=UUID.randomUUID().toString();put(item,"id",id);put(item,"name",name);put(item,"mime",mime);put(item,"source",r.uri);put(item,"time",System.currentTimeMillis());put(item,"status","Saving");put(item,"bytes",0);put(item,"uri",destination==null?"":destination.toString());put(item,"managed",destination==null);put(item,"etag",header(r,"ETag"));put(item,"modified",header(r,"Last-Modified"));Transfer t=new Transfer(item,r,session);queued.put(id,t);update(c,item);try{c.startService(new Intent(c,DownloadService.class).setAction("save").putExtra("id",id));}catch(Exception e){queued.remove(id);close(r.body);put(item,"status","Failed — could not start download service");update(c,item);}}
 static void action(Context c,String action,String id){Intent intent=new Intent(c,DownloadService.class).setAction(action).putExtra("id",id);try{c.startService(intent);}catch(Exception ignored){}}
 static void reconcile(Context c){synchronized(LOCK){JSONArray saved=records(c);for(int i=0;i<saved.length();i++){JSONObject o=saved.optJSONObject(i);if(o!=null&&"Saving".equals(o.optString("status"))&&!active.containsKey(o.optString("id"))&&!queued.containsKey(o.optString("id"))){put(o,"status","Paused — app was interrupted");}}c.getSharedPreferences("browser",0).edit().putString("downloads",saved.toString()).apply();}}
 static void setVisible(boolean value){visible=value;if(!value&&instance!=null)instance.pauseAll();}
 void pauseAll(){for(Transfer t:queued.values()){t.paused=true;close(t.response==null?null:t.response.body);put(t.item,"status","Paused — return to browser to resume");update(this,t.item);}queued.clear();for(Transfer t:active.values()){t.paused=true;close(t.input);if(t.response!=null)close(t.response.body);if(t.input==null)fail(t,"Paused — return to browser to resume");}finishIfIdle();}
 @Override public void onCreate(){super.onCreate();instance=this;wakeLock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"KosherBrowsing:downloads");wakeLock.acquire(6*60*60*1000L);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(CHANNEL,"Downloads",NotificationManager.IMPORTANCE_LOW));}
 @Override public IBinder onBind(Intent i){return null;}
 PendingIntent actionIntent(String action,String id){return PendingIntent.getActivity(this,(action+id).hashCode(),new Intent(this,MainActivity.class).putExtra("show_downloads",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 Notification notification(Transfer t,boolean ongoing){JSONObject o=t.item;String status=o.optString("status"),id=o.optString("id");long bytes=o.optLong("bytes"),total=o.optLong("total");Notification.Builder b=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle(o.optString("name","Download")).setContentText(status+" · "+android.text.format.Formatter.formatShortFileSize(this,bytes)+(total>0?" / "+android.text.format.Formatter.formatShortFileSize(this,total):"")).setOnlyAlertOnce(true).setOngoing(ongoing).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("show_downloads",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));if(ongoing){b.setProgress(100,total>0?(int)Math.min(100,bytes*100/total):0,total<=0);}else if(!"Complete".equals(status))b.addAction(new Notification.Action.Builder(null,"Manage transfer",actionIntent("resume",id)).build());return b.build();}
 void notifyItem(Transfer t,boolean ongoing){getSystemService(NotificationManager.class).notify(9000+(t.item.optString("id").hashCode()&0x3fffffff),notification(t,ongoing));}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(!visible){pauseAll();stopSelf();return START_NOT_STICKY;}if(intent==null){finishIfIdle();return START_NOT_STICKY;}String id=intent.getStringExtra("id"),action=intent.getAction();if("pause".equals(action)){Transfer t=active.get(id);if(t!=null){t.paused=true;close(t.input);if(t.response!=null)close(t.response.body);if(t.input==null)fail(t,"Paused");}finishIfIdle();return START_NOT_STICKY;}if(active.containsKey(id)){finishIfIdle();return START_NOT_STICKY;}Transfer t=queued.remove(id);if(t!=null){active.put(id,t);copy(t,0);}else if("resume".equals(action)){JSONObject o=find(this,id);if(o!=null&&!"Complete".equals(o.optString("status"))){t=new Transfer(o,null,null);active.put(id,t);resume(t);}else finishIfIdle();}else finishIfIdle();return START_NOT_STICKY;}
 void resume(Transfer t){if(DownloadPolicy.blocked(t.item.optString("name"),t.item.optString("mime"),t.item.optString("source"))){fail(t,"Blocked — APK downloads are disabled");return;}put(t.item,"status","Saving");update(this,t.item);BrowserEngine.ensure(this,new BrowserEngine.Ready(){public void failed(Throwable e){fail(t,"Paused — protections could not start");}public void ready(GeckoRuntime runtime,WebExtension ext){if(t.paused)return;String source=t.item.optString("source");if(!BrowserFeatures.http(source)){fail(t,"Failed — invalid download URL");return;}long saved=stage(t).isFile()?t.item.optLong("bytes"):0;String validator=t.item.optString("etag");if(validator.startsWith("W/"))validator="";if(validator.isEmpty())validator=t.item.optString("modified");final long offset=validator.isEmpty()?0:saved;t.session=new GeckoSession();t.ownSession=true;t.session.setContentDelegate(new GeckoSession.ContentDelegate(){@Override public void onExternalResponse(GeckoSession s,WebResponse response){if(t.paused||!active.containsValue(t)){close(response.body);return;}if(t.response!=null){close(response.body);return;}t.response=response;copy(t,offset);}@Override public void onCrash(GeckoSession s){fail(t,"Paused — browser process stopped");}});t.session.setNavigationDelegate(new GeckoSession.NavigationDelegate(){@Override public GeckoResult<AllowOrDeny> onLoadRequest(GeckoSession s,LoadRequest request){if("about:blank".equals(request.uri))return GeckoResult.fromValue(AllowOrDeny.ALLOW);boolean allowed=BrowserFeatures.http(request.uri);if(!allowed)fail(t,"Paused — request blocked");return GeckoResult.fromValue(allowed?AllowOrDeny.ALLOW:AllowOrDeny.DENY);}@Override public GeckoResult<String> onLoadError(GeckoSession s,String uri,WebRequestError error){fail(t,"Paused — network or policy error");return null;}@Override public GeckoResult<GeckoSession> onNewSession(GeckoSession s,String uri){return GeckoResult.fromValue(null);}});t.session.open(runtime);Map<String,String> headers=new HashMap<>();headers.put("X-Kosher-Resume","1");headers.put("Accept-Encoding","identity");if(offset>0){headers.put("Range","bytes="+offset+"-");headers.put("If-Range",validator);}t.session.load(new GeckoSession.Loader().uri(source).additionalHeaders(headers).headerFilter(GeckoSession.HEADER_FILTER_UNRESTRICTED_UNSAFE));main.postDelayed(()->{if(t.response==null&&active.containsValue(t))fail(t,"Paused — download timed out");},45000);}});}
 File stage(Transfer t){return new File(getCacheDir(),"transfer-"+t.item.optString("id")+".part");}
 void copy(Transfer t,long requestedOffset){io.execute(()->{Uri destination=null;long bytes=requestedOffset;try{WebResponse r=t.response;if(DownloadPolicy.blocked(t.item.optString("name"),t.item.optString("mime"),r==null?"":r.uri,r==null?"":header(r,"Content-Type"),r==null?"":header(r,"Content-Disposition")))throw new DownloadPolicy.BlockedPackage();if(r==null||r.body==null||r.statusCode<200||r.statusCode>=300)throw new IOException("Server did not return a file");String uri=t.item.optString("uri");destination=uri.isEmpty()?null:Uri.parse(uri);long offset=0;if(r.statusCode==206){String encoding=header(r,"Content-Encoding");if(!encoding.isEmpty()&&!encoding.equalsIgnoreCase("identity"))throw new IOException("Server sent encoded ranges");String oldTag=t.item.optString("etag"),newTag=header(r,"ETag");if(!oldTag.isEmpty()&&!newTag.isEmpty()&&!oldTag.equals(newTag))throw new IOException("File changed on server");String range=header(r,"Content-Range");java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("bytes (\\d+)-(\\d+)/(\\d+|\\*)").matcher(range);if(!matcher.matches()||Long.parseLong(matcher.group(1))!=requestedOffset)throw new IOException("Invalid resume range");offset=requestedOffset;if(!matcher.group(3).equals("*"))put(t.item,"total",Long.parseLong(matcher.group(3)));}else{offset=0;try{put(t.item,"total",header(r,"Content-Encoding").isEmpty()?Long.parseLong(header(r,"Content-Length")):0);}catch(Exception ignored){put(t.item,"total",0);}}bytes=offset;put(t.item,"etag",header(r,"ETag"));put(t.item,"modified",header(r,"Last-Modified"));put(t.item,"status","Saving");put(t.item,"bytes",bytes);update(this,t.item);t.input=r.body;r.setReadTimeoutMillis(30000);if(t.paused)throw new IOException("Paused");
    try(RandomAccessFile out=new RandomAccessFile(stage(t),"rw")){FileChannel channel=out.getChannel();if(offset>channel.size())throw new IOException("Partial file is missing");channel.truncate(offset);channel.position(offset);byte[] buffer=new byte[32768];int n;long next=0;while(!t.paused&&(n=t.input.read(buffer))!=-1){out.write(buffer,0,n);bytes+=n;if(System.currentTimeMillis()>=next){put(t.item,"bytes",bytes);update(this,t.item);notifyItem(t,true);next=System.currentTimeMillis()+1000;}}channel.force(true);}
    if(t.paused)throw new IOException("Paused");long total=t.item.optLong("total");if(total>0&&bytes!=total)throw new IOException("Incomplete response");DownloadPolicy.verify(stage(t));if(destination==null){if(Build.VERSION.SDK_INT<29)throw new IOException("Choose a download location again");ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,t.item.optString("name"));values.put(MediaStore.MediaColumns.MIME_TYPE,t.item.optString("mime"));values.put(MediaStore.MediaColumns.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/Kosher Browsing");values.put(MediaStore.MediaColumns.IS_PENDING,1);destination=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(destination==null)throw new IOException("Cannot create download");put(t.item,"uri",destination.toString());update(this,t.item);}
    try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(destination,"rwt")){if(fd==null)throw new IOException("Cannot open destination");try(FileOutputStream out=new ParcelFileDescriptor.AutoCloseOutputStream(fd);InputStream saved=new FileInputStream(stage(t))){byte[] buffer=new byte[32768];int n;while((n=saved.read(buffer))!=-1){if(t.paused)throw new IOException("Paused");out.write(buffer,0,n);}out.flush();}}
    if(t.item.optBoolean("managed")&&Build.VERSION.SDK_INT>=29){ContentValues done=new ContentValues();done.put(MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(destination,done,null,null);}put(t.item,"status","Complete");stage(t).delete();
   }catch(Exception e){if(e instanceof DownloadPolicy.BlockedPackage){stage(t).delete();put(t.item,"status","Blocked — APK downloads are disabled");}else put(t.item,"status",t.paused?"Paused":"Paused — "+(e.getMessage()==null?"transfer interrupted":e.getMessage()));}finally{close(t.input);if(t.response!=null)close(t.response.body);put(t.item,"bytes",bytes);update(this,t.item);main.post(()->finish(t));}});}
 void fail(Transfer t,String status){if(!active.containsValue(t))return;put(t.item,"status",status);update(this,t.item);finish(t);}
 void finish(Transfer t){String id=t.item.optString("id");if(!active.remove(id,t))return;notifyItem(t,false);if(t.session!=null&&(t.ownSession||detached.contains(t.session))){GeckoSession s=t.session;boolean used=false;for(Transfer other:active.values())if(other.session==s)used=true;if(!used){detached.remove(s);s.close();}}finishIfIdle();}
 void finishIfIdle(){if(active.isEmpty()&&queued.isEmpty()){stopSelf();}}
 @Override public void onDestroy(){pauseAll();if(instance==this)instance=null;if(wakeLock!=null&&wakeLock.isHeld())wakeLock.release();io.shutdown();super.onDestroy();}
 static void close(InputStream in){if(in!=null)try{in.close();}catch(Exception ignored){}}
}
